mapper.insert:
INSERT INTO career_loop_stage_log(
    session_id, from_stage, to_stage, trigger_source, trigger_ref_id, note, create_time
) VALUES (
    #{sessionId}, #{fromStage}, #{toStage}, #{triggerSource}, #{triggerRefId}, #{note}, NOW()
)

mapper.select:
SELECT
    log.id, log.session_id, session.user_id, log.from_stage, log.to_stage, log.trigger_source,
    log.trigger_ref_id, log.note, log.create_time
FROM career_loop_stage_log log
INNER JOIN career_loop_session session ON session.id = log.session_id
WHERE session.user_id = #{userId}

    AND (log.create_time > #{afterCreateTime}
        OR (log.create_time = #{afterCreateTime} AND log.id >= #{afterSourceId}))

ORDER BY log.create_time ASC, log.id ASC
LIMIT #{limit}
